"""Necessary Apache-2.0 ESPnet 202308 reference sources; offline only.

Original class/function bodies and checkpoint state, with package imports
replaced by small interfaces. Legacy torch_complex behavior is preserved.
See ../speech_denoising/models/tfgridnet/PRETRAINED.md and LICENSE.upstream.
"""
import ast
import base64
import hashlib
import json
import zlib

import torch
from torch import nn

REFERENCE_REVISION = "01d7df74f711758edab1d90b24e2f0859e0b31da"
REFERENCES = json.loads('{"espnet2/enh/layers/complex_utils.py": {"sha256": "95b27b87a07849f00b7b254c43acd009dd14125f96cd8a08bec2bdf3f5e26663", "compressed": ""}, "espnet2/layers/stft.py": {"sha256": "cbde9989cdb0ebf6c8cc78fdae466879d35b95f6e48637ca072377e460ceb426", "compressed": ""}, "espnet2/enh/encoder/stft_encoder.py": {"sha256": "330d9ab2988f55806915adc4ec66efb8b077b6c416c4d2b873cdfdc79d9070dd", "compressed": ""}, "espnet2/enh/decoder/stft_decoder.py": {"sha256": "478e625239330b2ba07cd8640f26252aecadc476c355b347c708b8cf1c014772", "compressed": ""}, "espnet2/torch_utils/get_layer_from_string.py": {"sha256": "f8821d9566f326f75e69339eca18fa3b84d81b84915502dddbfe64b30dc0884e", "compressed": ""}, "espnet2/enh/separator/tfgridnet_separator.py": {"sha256": "4e0fe975116a1dc12904111588e4f8f5ae779e91ec6945d99756ddac2ec72f52", "compressed": ""}}')



def reference_class():
    # The 202308 release calls iSTFT with [..., real/imag]. PyTorch 2.x
    # requires builtin complex at that API boundary. Keep all upstream
    # computation bodies intact and bridge only that representation.
    class FunctionalCompatibility:
        def __getattr__(self, name):
            return getattr(torch.functional, name)

        @staticmethod
        def istft(input, *args, **kwargs):
            if not torch.is_complex(input):
                if input.shape[-1] != 2:
                    raise ValueError("Reference iSTFT expects real/imag pairs")
                input = torch.complex(input[..., 0], input[..., 1])
            return torch.functional.istft(input, *args, **kwargs)

    class TorchCompatibility:
        functional = FunctionalCompatibility()

        def __getattr__(self, name):
            return getattr(torch, name)

    class InversibleInterface:
        pass

    def make_pad_mask(lengths, tensor, length_dim):
        if length_dim != 1:
            raise AssertionError("Reference only masks frame axis one")
        index = torch.arange(tensor.shape[1], device=tensor.device)[None, :]
        mask = index >= lengths.to(tensor.device)[:, None]
        return mask.view(*mask.shape, *([1] * (tensor.ndim - 2))).expand_as(tensor)

    namespace = dict(__name__="_espnet_202308_dns_reference", AbsSeparator=nn.Module,
                     AbsEncoder=nn.Module, AbsDecoder=nn.Module,
                     InversibleInterface=InversibleInterface,
                     check_argument_types=lambda: True, make_pad_mask=make_pad_mask)
    for name, record in REFERENCES.items():
        raw = zlib.decompress(base64.b64decode(record["compressed"]))
        if hashlib.sha256(raw).hexdigest() != record["sha256"]:
            raise RuntimeError("Embedded reference checksum mismatch: " + name)
        tree = ast.parse(raw.decode(), filename=name)
        nodes = []
        for node in tree.body:
            if isinstance(node, ast.ImportFrom) and node.module.startswith(("espnet", "typeguard")):
                continue
            if isinstance(node, ast.Import) and any(alias.name == "librosa" for alias in node.names):
                continue  # Only unused pre-PyTorch-1.10 fallback needs librosa.
            if name.endswith("complex_utils.py") and isinstance(node, ast.FunctionDef):
                if node.name not in {"new_complex_like", "is_torch_complex_tensor", "is_complex"}:
                    continue
            nodes.append(node)
        tree.body = nodes
        exec(compile(tree, name, "exec"), namespace)
        namespace["torch"] = TorchCompatibility()
    return namespace["TFGridNet"]
